-- =============================================================================
-- Schéma PostgreSQL — migré depuis clients.db (SQLite)
-- Compatible PostgreSQL 13+ (testé sur 16, cible 18)
--
-- Conversions de types appliquées :
--   INTEGER PRIMARY KEY AUTOINCREMENT  -> bigint GENERATED BY DEFAULT AS IDENTITY
--   TEXT contenant des dates          -> date
--   REAL (quantity)                   -> numeric(12,3)   (calcul monétaire exact)
--   INTEGER 0/1 (is_active)           -> boolean
--   DEFAULT (date('now'))             -> DEFAULT CURRENT_DATE
-- Les CHECK, UNIQUE, FK (avec leurs ON DELETE), index et la vue sont repris à l'identique.
-- =============================================================================

BEGIN;

-- -----------------------------------------------------------------------------
-- customers
-- -----------------------------------------------------------------------------
CREATE TABLE customers (
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code         text    NOT NULL,
  title        text,
  last_name    text    NOT NULL,
  first_name   text,
  type         text    NOT NULL DEFAULT 'individual',
  company_name text,
  email        text,
  phone        text,
  address      text,
  postal_code  text,
  city         text,
  notes        text,
  created_at   date    NOT NULL DEFAULT CURRENT_DATE,

  CONSTRAINT customers_code_key    UNIQUE (code),
  CONSTRAINT customers_title_check CHECK (title IN ('Mr','Mrs')),
  CONSTRAINT customers_type_check  CHECK (type  IN ('individual','business'))
);

-- -----------------------------------------------------------------------------
-- products
-- -----------------------------------------------------------------------------
CREATE TABLE products (
  id               bigint  GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sku              text    NOT NULL,
  name             text    NOT NULL,
  category         text    NOT NULL,
  unit             text    NOT NULL,
  unit_price_cents integer NOT NULL,
  vat_rate_bp      integer NOT NULL DEFAULT 2000,
  is_active        boolean NOT NULL DEFAULT true,
  created_at       date    NOT NULL DEFAULT CURRENT_DATE,

  CONSTRAINT products_sku_key              UNIQUE (sku),
  CONSTRAINT products_category_check       CHECK (category IN ('supply','labor','travel')),
  CONSTRAINT products_unit_check           CHECK (unit IN ('unit','hour','meter','sqm','flat')),
  CONSTRAINT products_unit_price_cents_chk CHECK (unit_price_cents >= 0),
  CONSTRAINT products_vat_rate_bp_check    CHECK (vat_rate_bp IN (2000,1000,550))
);

-- -----------------------------------------------------------------------------
-- documents (devis + factures, auto-référence quote_id -> devis d'origine)
-- -----------------------------------------------------------------------------
CREATE TABLE documents (
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  number       text   NOT NULL,
  type         text   NOT NULL,
  customer_id  bigint NOT NULL,
  quote_id     bigint,
  status       text   NOT NULL,
  subject      text,
  issue_date   date   NOT NULL,
  valid_until  date,
  due_date     date,
  paid_at      date,
  notes        text,
  created_at   date   NOT NULL DEFAULT CURRENT_DATE,

  CONSTRAINT documents_number_key UNIQUE (number),
  CONSTRAINT documents_type_check CHECK (type IN ('quote','invoice')),
  CONSTRAINT documents_customer_id_fkey
    FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT,
  CONSTRAINT documents_quote_id_fkey
    FOREIGN KEY (quote_id)    REFERENCES documents(id) ON DELETE SET NULL,
  CONSTRAINT documents_type_status_check CHECK (
       (type = 'quote'   AND status IN ('draft','sent','accepted','rejected','expired')
                         AND quote_id IS NULL AND due_date IS NULL AND paid_at IS NULL)
    OR (type = 'invoice' AND status IN ('draft','issued','paid','overdue','cancelled')
                         AND valid_until IS NULL)
  ),
  CONSTRAINT documents_paid_at_check CHECK (status <> 'paid' OR paid_at IS NOT NULL)
);

-- -----------------------------------------------------------------------------
-- document_lines
-- -----------------------------------------------------------------------------
CREATE TABLE document_lines (
  id               bigint        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  document_id      bigint        NOT NULL,
  product_id       bigint,
  position         integer       NOT NULL,
  description      text          NOT NULL,
  quantity         numeric(12,3) NOT NULL,
  unit             text          NOT NULL,
  unit_price_cents integer       NOT NULL,
  vat_rate_bp      integer       NOT NULL,
  discount_bp      integer       NOT NULL DEFAULT 0,

  CONSTRAINT document_lines_document_id_position_key UNIQUE (document_id, position),
  CONSTRAINT document_lines_document_id_fkey
    FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE,
  CONSTRAINT document_lines_product_id_fkey
    FOREIGN KEY (product_id)  REFERENCES products(id)  ON DELETE SET NULL,
  CONSTRAINT document_lines_quantity_check         CHECK (quantity > 0),
  CONSTRAINT document_lines_unit_price_cents_check CHECK (unit_price_cents >= 0),
  CONSTRAINT document_lines_vat_rate_bp_check      CHECK (vat_rate_bp IN (2000,1000,550)),
  CONSTRAINT document_lines_discount_bp_check      CHECK (discount_bp BETWEEN 0 AND 10000)
);

-- -----------------------------------------------------------------------------
-- Index (identiques à la base SQLite)
-- -----------------------------------------------------------------------------
CREATE INDEX idx_documents_customer     ON documents(customer_id);
CREATE INDEX idx_documents_type_status  ON documents(type, status);
CREATE INDEX idx_document_lines_product ON document_lines(product_id);

-- -----------------------------------------------------------------------------
-- Vue des totaux par document (montants en centimes)
-- round(numeric) arrondit "half away from zero", comme ROUND() de SQLite.
-- -----------------------------------------------------------------------------
CREATE VIEW v_document_totals AS
SELECT d.id, d.number, d.type, d.status, d.customer_id,
       SUM(ROUND(l.quantity * l.unit_price_cents * (10000 - l.discount_bp) / 10000.0))::bigint
         AS total_excl_vat_cents,
       SUM(ROUND(l.quantity * l.unit_price_cents * (10000 - l.discount_bp) / 10000.0
                 * l.vat_rate_bp / 10000.0))::bigint
         AS total_vat_cents
FROM documents d
LEFT JOIN document_lines l ON l.document_id = d.id
GROUP BY d.id;

-- -----------------------------------------------------------------------------
-- Rôles des agents loom (examples/agent_postgres)
-- loom.sql refuse un rôle superutilisateur ou BYPASSRLS : chaque agent a son
-- rôle, avec exactement les droits déclarés dans sa config. Les mots de passe
-- sont ceux du .env de l'agent (base de test).
-- Les rôles appartiennent à l'instance : on ne les crée que s'ils manquent.
-- -----------------------------------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'loom_compta') THEN
    CREATE ROLE loom_compta LOGIN PASSWORD 'compta'
      NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'loom_analyste') THEN
    CREATE ROLE loom_analyste LOGIN PASSWORD 'analyste'
      NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE;
  END IF;
  EXECUTE format('GRANT CONNECT ON DATABASE %I TO loom_compta, loom_analyste',
                 current_database());
  -- Sans ce REVOKE, loom avertit « TEMP sur la base » : PUBLIC peut créer des tables temporaires.
  EXECUTE format('REVOKE TEMP ON DATABASE %I FROM PUBLIC', current_database());
END
$$;

GRANT USAGE ON SCHEMA public TO loom_compta, loom_analyste;

-- compta : lecture des clients, du catalogue et des documents ; modification des documents
GRANT SELECT ON customers, products, documents TO loom_compta;
GRANT UPDATE ON documents TO loom_compta;

-- analyste : lecture seule des tables et de la vue de calcul
GRANT SELECT ON customers, products, documents, document_lines, v_document_totals
  TO loom_analyste;

COMMIT;
